const $=s=>document.querySelector(s);
$('#bottom-saved').onclick=()=>{$('#saved').click();$('#main').scrollIntoView()};let edition,category='Tutte',onlySaved=false,lastFocus;
const storage={get(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{$('#status').textContent='Preferenze disponibili solo in questa sessione.'}}};let saved=new Set(storage.get('saved',[]));let theme=storage.get('theme',matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
function applyTheme(){document.body.dataset.theme=theme;$('#theme').setAttribute('aria-label',theme==='dark'?'Attiva modalità chiara':'Attiva modalità scura');document.querySelector('meta[name=theme-color]').content=theme==='dark'?'#191f1c':'#f5f2eb'}applyTheme();$('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';storage.set('theme',theme);applyTheme()};
const categories=['Tutte','Politica','Esteri','Economia','Cronaca','Roma','Cultura · Teatro · Cinema','Tecnologia · AI'];
function el(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}function date(s){return s?new Intl.DateTimeFormat('it-IT',{dateStyle:'long',timeZone:'Europe/Rome'}).format(new Date(s)):'Non applicabile · esempio'}
function button(text,fn,cls){const b=el('button',text,cls);b.onclick=fn;return b}function badge(a){return `${a.category} / ${a.status==='example'?'Esempio':a.status==='archive'?'Archivio':'Verificata'}`}
function photo(a){const f=el('figure',null,'photo'),im=el('img');im.src=a.image.src;im.alt=a.image.alt;im.loading='lazy';im.width=800;im.height=500;im.onerror=()=>{im.hidden=true;f.prepend(el('p','Fotografia non disponibile. Apri la fonte originale.'))};const cap=el('figcaption',a.image.caption||'');const credit=el('a',a.image.credit+' · '+a.image.rights);credit.href=a.image.sourceUrl;credit.target='_blank';credit.rel='noopener noreferrer';cap.append(document.createTextNode(' '),credit);if(a.image.licenseUrl){const lic=el('a',' · Licenza');lic.href=a.image.licenseUrl;lic.target='_blank';lic.rel='noopener noreferrer';cap.append(lic)}f.append(im,cap);return f}
function actions(a){const box=el('div',null,'actions');box.append(button('Leggi approfondimento ↗',()=>open(a),'read'));const b=button(saved.has(a.id)?'Salvata ✓':'Salva +',()=>{saved.has(a.id)?saved.delete(a.id):saved.add(a.id);storage.set('saved',[...saved]);render();$('#status').textContent=saved.has(a.id)?'Storia salvata.':'Storia rimossa dai salvati.'},'bookmark');b.setAttribute('aria-label',`${saved.has(a.id)?'Rimuovi dai salvati':'Salva'}: ${a.title}`);b.setAttribute('aria-pressed',saved.has(a.id));box.append(b);return box}
function match(a){return(category==='Tutte'||a.category===category)&&(!onlySaved||saved.has(a.id))}function render(){const nav=$('#categories');nav.replaceChildren();categories.forEach(c=>{const b=button(c,()=>{category=c;render()});b.setAttribute('aria-pressed',c===category);nav.append(b)});$('#count').textContent=saved.size;$('#saved').setAttribute('aria-pressed',onlySaved);let total=0;
for(const [key,target] of [['essentialIds','#essentials'],['leadIds','#leads'],['compactIds','#compact']]){const container=$(target);container.replaceChildren();edition[key].forEach((id,i)=>{const a=edition.articles.find(x=>x.id===id);if(!a||!match(a))return;total++;if(key==='essentialIds'){const e=el('div',null,'essential');e.append(el('span',String(i+1).padStart(2,'0'),'number'),button(a.title,()=>open(a)));container.append(e);return}const e=el('article',null,key==='leadIds'?'story':'small-story');if(a.image)e.append(photo(a));const text=el('div');text.append(el('span',badge(a),'tag'),el('h3',a.title),el('p',a.summary),actions(a));e.append(text);container.append(e)})}$('#empty').hidden=total!==0;$('#essential-section').hidden=!$('#essentials').children.length;$('#lead-count').textContent=String($('#leads').children.length).padStart(2,'0')+' / STORIE';}
function open(a){lastFocus=document.activeElement;const c=$('#reader-content');c.replaceChildren(el('span',badge(a),'tag'),el('h2',a.title));if(a.image)c.append(photo(a));a.body.forEach(p=>c.append(el('p',p)));c.append(el('p',(a.dateKind==='event'?'Data evento: ':'Pubblicato: ')+date(a.publishedAt),'meta'));if(a.verifiedAt)c.append(el('p','Verificato: '+date(a.verifiedAt)+(a.status==='archive'?'. Contenuto di archivio.':'. Fonte accessibile senza abbonamento al controllo.'),'meta'));if(a.source){const link=el('a','Apri la fonte gratuita · '+a.source.name);link.href=a.source.url;link.target='_blank';link.rel='noopener noreferrer';c.append(link);if(a.image){const provenance=el('p',null,'meta');const l=el('a','Provenienza della fotografia');l.href=a.image.sourceUrl;l.target='_blank';l.rel='noopener noreferrer';provenance.append(l);c.append(provenance)}}else c.append(el('p','Nessuna fonte: scheda esemplificativa senza notizie reali.','meta'));$('#reader').showModal();$('#reader').scrollTop=0}
$('#close').onclick=()=>$('#reader').close();$('#reader').addEventListener('close',()=>lastFocus?.focus());$('#saved').onclick=()=>{onlySaved=!onlySaved;render()};
async function load(){try{const r=await fetch('data/current.json',{cache:'no-store'});if(!r.ok)throw Error();const next=await r.json();if(next.schemaVersion!==1||!Array.isArray(next.articles)||!next.essentialIds||!next.leadIds||!next.compactIds)throw Error();edition=next;$('#date').textContent=(edition.mode==='demo'?'DEMO · ':'EDIZIONE · ')+date(edition.editionDate+'T12:00:00+01:00');$('.notice').hidden=edition.mode!=='demo';if(edition.mode==='live'){$('.about>p').textContent='13 storie selezionate con fonti gratuite. Edizione del 27 ottobre 2026: ogni approfondimento distingue la data di pubblicazione da quella dei fatti.';$('.dateline span:last-child').textContent='Edizione mattina';}if(edition.mode!=='demo'){$('#connection').textContent='Ultima edizione: '+date(edition.editionDate+'T12:00:00+01:00');if(edition.editionDate!==new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Rome'}).format(new Date()))$('#status').textContent='Edizione precedente: l’aggiornamento di oggi non è ancora disponibile.'}render();return true}catch{$('#status').textContent=edition?'Aggiornamento non disponibile. Resta visibile l’ultima edizione caricata.':'Impossibile caricare l’edizione. Riprova quando sei online.';return false}}
$('#refresh').onclick=async()=>{if(await load())$('#status').textContent=edition.mode==='demo'?'Demo aggiornata. Il flusso giornaliero non è collegato.':'Edizione caricata: '+date(edition.editionDate+'T12:00:00+01:00')};function connection(){$('#connection').textContent=navigator.onLine?'Connessione disponibile · la lettura offline si prepara alla prima apertura.':'Sei offline · stai leggendo l’ultima edizione disponibile su questo dispositivo.'}addEventListener('online',connection);addEventListener('offline',connection);connection();await load();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{$('#connection').textContent='Lettura offline non disponibile in questo browser.'});
